package com.srent.media;
import com.srent.common.BaseEntity; import com.srent.room.Room; import com.srent.user.User; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="room_videos") @Getter @Setter @NoArgsConstructor
public class RoomVideo extends BaseEntity { public enum Status{UPLOADING,PENDING,APPROVED,REJECTED} @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="room_id",nullable=false) private Room room; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="uploader_id",nullable=false) private User uploader; @Column(name="object_key",nullable=false,unique=true) private String objectKey; @Column(name="upload_token",nullable=false,unique=true) private String uploadToken; @Column(name="content_type",nullable=false) private String contentType; @Column(name="size_bytes") private Long sizeBytes; @Column(name="device_latitude",nullable=false) private BigDecimal deviceLatitude; @Column(name="device_longitude",nullable=false) private BigDecimal deviceLongitude; @Column(name="gps_accuracy_meters",nullable=false) private BigDecimal gpsAccuracyMeters; @Column(name="captured_at",nullable=false) private Instant capturedAt; @Column(name="distance_meters",nullable=false) private BigDecimal distanceMeters; @Enumerated(EnumType.STRING) @Column(nullable=false) private Status status=Status.UPLOADING; @Column(name="review_note") private String reviewNote; }
